        "pfad_tag_verfuegbar_morgen": ["de": "Morgen verfügbar", "en": "Available tomorrow", "es": "Disponible mañana", "fr": "Disponible demain", "it": "Disponibile domani", "pt": "Disponível amanhã"],
        "pfad_meilenstein_titel": ["de": "Meilenstein erreicht!", "en": "Milestone reached!", "es": "¡Hito alcanzado!", "fr": "Jalon atteint !", "it": "Traguardo raggiunto!", "pt": "Marco alcançado!"],
        "pfad_leer_titel": ["de": "Dein Pfad", "en": "Your Path", "es": "Tu camino", "fr": "Ton chemin", "it": "Il tuo percorso", "pt": "O teu caminho"],
        "pfad_leer_beschreibung": ["de": "Dein Pfad beginnt beim ersten Start der App.", "en": "Your path starts when you first open the app.", "es": "Tu camino comienza cuando abres la app por primera vez.", "fr": "Ton chemin commence quand tu ouvres l'application pour la première fois.", "it": "Il tuo percorso inizia al primo avvio dell'app.", "pt": "O teu caminho começa quando abres a aplicação pela primeira vez."],
        "pfad_fit_day_1_title": ["de": "Der erste Schritt", "en": "The First Step", "es": "El primer paso", "fr": "Le premier pas", "it": "Il primo passo", "pt": "O primeiro passo"],
        "pfad_fit_day_1_desc": ["de": "Mach heute 10 Liegestütze. Qualität vor Quantität.", "en": "Do 10 pushups today. Quality over quantity.", "es": "Haz 10 flexiones hoy. Calidad sobre cantidad.", "fr": "Fais 10 pompes aujourd'hui. Qualité avant quantité.", "it": "Fai 10 flessioni oggi. Qualità prima della quantità.", "pt": "Faz 10 flexões hoje. Qualidade acima de quantidade."],
        "pfad_fit_day_7_title": ["de": "Eine Woche!", "en": "One Week!", "es": "¡Una semana!", "fr": "Une semaine !", "it": "Una settimana!", "pt": "Uma semana!"],
        "pfad_fit_day_7_desc": ["de": "20 Liegestütze heute. Du hast bewiesen dass du es kannst.", "en": "20 pushups today. You've proven that you can do it.", "es": "20 flexiones hoy. Has demostrado que puedes hacerlo.", "fr": "20 pompes aujourd'hui. Tu as prouvé que tu en es capable.", "it": "20 flessioni oggi. Hai dimostrato di potercela fare.", "pt": "20 flexões hoje. Provaste que consegues fazê-lo."],
        "pfad_fit_day_14_title": ["de": "Zwei Wochen!", "en": "Two Weeks!", "es": "¡Dos semanas!", "fr": "Deux semaines !", "it": "Due settimane!", "pt": "Duas semanas!"],
        "pfad_fit_day_14_desc": ["de": "25 Liegestütze + 2 Minuten Plank. Du bist auf dem Weg zur Meisterschaft.", "en": "25 pushups + 2 minutes plank. You're on your way to mastery.", "es": "25 flexiones + 2 minutos de plancha. Estás de camino a la maestría.", "fr": "25 pompes + 2 minutes de gainage. Tu es sur la voie de la maîtrise.", "it": "25 flessioni + 2 minuti di plank. Sei sulla strada per la maestria.", "pt": "25 flexões + 2 minutos de prancha. Estás no caminho para a mestria."],
        "pfad_fit_day_30_title": ["de": "Ein Monat!", "en": "One Month!", "es": "¡Un mes!", "fr": "Un mois !", "it": "Un mese!", "pt": "Um mês!"],
        "pfad_fit_day_30_desc": ["de": "30 Tage Fitness. Heute: maximale Leistung — so viele Liegestütze wie möglich.", "en": "30 days of fitness. Today: maximum performance — as many pushups as possible.", "es": "30 días de fitness. Hoy: rendimiento máximo - tantas flexiones como sea posible.", "fr": "30 jours de fitness. Aujourd'hui : performance maximale — autant de pompes que possible.", "it": "30 giorni di fitness. Oggi: prestazioni massime.", "pt": "30 dias de fitness. Hoje: desempenho máximo."],
        "pfad_produktiv_day_1_title": ["de": "Fokus-Zeit", "en": "Focus Time", "es": "Tiempo de enfoque", "fr": "Temps de concentration", "it": "Tempo di concentrazione", "pt": "Tempo de foco"],
        "pfad_produktiv_day_1_desc": ["de": "Arbeite heute 25 Minuten ohne Ablenkung.", "en": "Work for 25 minutes without distraction today.", "es": "Trabaja hoy 25 minutos sin distracciones.", "fr": "Travaille 25 minutes sans distraction aujourd'hui.", "it": "Lavora per 25 minuti senza distrazioni oggi.", "pt": "Trabalha 25 minutos sem distração hoje."],
        "pfad_produktiv_day_7_title": ["de": "Wochenplanung", "en": "Weekly Planning", "es": "Planificación semanal", "fr": "Planification hebdomadaire", "it": "Pianificazione settimanale", "pt": "Planeamento semanal"],
        "pfad_produktiv_day_7_desc": ["de": "Plane heute deine kommenden 7 Tage im Voraus.", "en": "Plan your next 7 days in advance today.", "es": "Planifica hoy tus próximos 7 días con antelación.", "fr": "Planifie aujourd'hui tes 7 prochains jours à l'avance.", "it": "Pianifica oggi i tuoi prossimi 7 giorni in anticipo.", "pt": "Planeia hoje os teus próximos 7 dias com antecedência."],
        "pfad_mental_day_1_title": ["de": "Pause", "en": "Break", "es": "Descanso", "fr": "Pause", "it": "Pausa", "pt": "Pausa"],
        "pfad_mental_day_1_desc": ["de": "Nimm dir heute 2 Minuten nur zum Atmen.", "en": "Take 2 minutes today just to breathe.", "es": "Tómate 2 minutos hoy solo para respirar.", "fr": "Prends 2 minutes aujourd'hui juste pour respirer.", "it": "Prenditi 2 minuti oggi solo per respirare.", "pt": "Dedica 2 minutos hoje só para respirar."],
        "pfad_lernen_day_1_title": ["de": "Wissensdurst", "en": "Thirst for Knowledge", "es": "Sed de conocimiento", "fr": "Soif de connaissance", "it": "Sete di conoscenza", "pt": "Sede de conhecimento"],
        "pfad_lernen_day_1_desc": ["de": "Lies heute genau 5 Seiten in einem Buch.", "en": "Read exactly 5 pages in a book today.", "es": "Lee hoy exactamente 5 páginas de un libro.", "fr": "Lis exactement 5 pages d'un livre aujourd'hui.", "it": "Leggi esattamente 5 pagine di un libro oggi.", "pt": "Lê exatamente 5 páginas num livre hoje."],
        "pfad_gesund_day_1_title": ["de": "Hydrierung", "en": "Hydration", "es": "Hidratación", "fr": "Hydratation", "it": "Idratazione", "pt": "Hidratação"],
        "pfad_gesund_day_1_desc": ["de": "Trinke heute 2 Liter Wasser.", "en": "Drink 2 liters of water today.", "es": "Bebe hoy 2 litros de agua.", "fr": "Bois 2 litres d'eau aujourd'hui.", "it": "Bevi 2 litri d'acqua oggi.", "pt": "Bebe 2 litros de água hoje."],
        "pfad_fehlt_day_1_title": ["de": "Eigener Start", "en": "Your Own Start", "es": "Tu propio inicio", "fr": "Ton propre début", "it": "Il tuo inizio", "pt": "O teu próprio início"],
        "pfad_fehlt_day_1_desc": ["de": "Erster Tag deines persönlichen Ziels.", "en": "First day of your personal goal.", "es": "Primer día de tu objetivo personal.", "fr": "Premier jour de ton objectif personnel.", "it": "Primo giorno del tuo obiettivo personale.", "pt": "Primeiro dia do teu objetivo pessoal."],
        "pfad_fit_phase_einstieg_desc": ["de": "Gewöhne deinen Körper an tägliche Bewegung. Kleine Schritte führen weit.", "en": "Get your body used to daily movement. Small steps go a long way.", "es": "Acostumbra tu cuerpo al movimiento diario. Los pequeños pasos llevan lejos.", "fr": "Habitue ton corps à une activité quotidienne. Les petits pas mènent loin.", "it": "Abitua il tuo corpo al movimento quotidiano. Piccoli passi portano lontano.", "pt": "Habitua o teu corpo ao movimento diário. Pequenos passos levam longe."],
        "pfad_produktiv_phase_einstieg_desc": ["de": "Finde deinen Rhythmus. Eine fokussierte Einheit heute.", "en": "Find your rhythm. One focused session today.", "es": "Encuentra tu ritmo. Una sesión enfocada hoy.", "fr": "Trouve ton rythme. Une session concentrée aujourd'hui.", "it": "Trova il tuo ritmo. Una sessione focalizzata oggi.", "pt": "Encontra o teu ritmo. Uma sessão focada hoje."],
        "pfad_mental_phase_einstieg_desc": ["de": "Kleine Auszeiten für den Geist. Lerne bewusstes Atmen.", "en": "Short breaks for the mind. Learn conscious breathing.", "es": "Pequeños descansos para la mente. Aprende a respirar conscientemente.", "fr": "Courtes pauses pour l'esprit. Apprends la respiration consciente.", "it": "Brevi pause per la mente. Impara la respirazione consapevole.", "pt": "Curta pausa para a mente. Aprende a respiração consciente."],
        "pfad_lernen_phase_einstieg_desc": ["de": "Baue deine tägliche Lesegewohnheit auf. Ein paar Seiten am Tag helfen.", "en": "Build your daily reading habit. A few pages a day help.", "es": "Crea tu hábito de lectura diario. Unas pocas páginas al día ayudan.", "fr": "Crée une habitude de lecture quotidienne. Quelques pages par jour aident.", "it": "Sviluppa la tua abitudine di lettura quotidiana. Poche pagine al giorno aiutano.", "pt": "Constrói o teu hábito diário de leitura. Algumas páginas por dia ajudam."],
        "pfad_gesund_phase_einstieg_desc": ["de": "Achte auf deine tägliche Wasserzufuhr für mehr Lebensenergie.", "en": "Pay attention to your daily water intake for more vital energy.", "es": "Presta atención a tu ingesta diaria de agua para tener más energía vital.", "fr": "Fais attention à ton apport quotidien en eau pour plus d'énergie vitale.", "it": "Fai attenzione al tuo apporto giornaliero di acqua per più energia vitale.", "pt": "Presta atenção à tua ingestão diária de água para mais energia vital."],
        "pfad_fehlt_phase_einstieg_desc": ["de": "Der Beginn von etwas Großem. Dein persönliches Ziel wartet.", "en": "The beginning of something great. Your personal goal awaits.", "es": "El comienzo de algo grande. Tu objetivo personal te espera.", "fr": "Le début de quelque chose de grand. Ton objectif personnel t'attend.", "it": "L'inizio di qualcosa di grande. Il tuo obiettivo personale ti aspetta.", "pt": "O início de algo grande. O teu objetivo pessoal espera por ti."],
        "pfad_fit_day_45_title": ["de": "Halbzeit!", "en": "Halfway!", "es": "¡Mitad del camino!", "fr": "À mi-chemin !", "it": "Metà strada!", "pt": "Meio do caminho!"],
        "pfad_fit_day_45_desc": ["de": "45 Tage Fitness. Dein Körper hat sich bereits verändert. Bleib stark!", "en": "45 days of fitness. Your body has already changed. Stay strong!", "es": "45 días de fitness. Tu cuerpo ya ha cambiado. ¡Mantente fuerte!", "fr": "45 jours de fitness. Ton corps a déjà changé. Reste fort !", "it": "45 giorni di fitness. Il tuo corpo è già cambiato. Rimani forte!", "pt": "45 dias de fitness. O teu corpo já mudou. Mantém-te forte!"],
        "pfad_fit_day_60_title": ["de": "Zwei Monate!", "en": "Two Months!", "es": "¡Dos meses!", "fr": "Deux mois !", "it": "Due mesi!", "pt": "Dois meses!"],
        "pfad_fit_day_60_desc": ["de": "60 Tage. Fitness ist nun ein fester Teil deines Lebens.", "en": "60 days. Fitness is now a fixed part of your life.", "es": "60 días. El fitness es ahora una parte fija de tu vida.", "fr": "60 jours. Le fitness fait maintenant partie intégrante de ta vie.", "it": "60 giorni. Il fitness è ormai una parte fissa della tua vita.", "pt": "60 dias. O fitness é agora uma parte fixa da tua vida."],
        "pfad_fit_day_90_title": ["de": "Meisterschaft erreicht!", "en": "Mastery reached!", "es": "¡Maestría alcanzada!", "fr": "Maîtrise atteinte !", "it": "Maestria raggiunta!", "pt": "Mestria alcançada!"],
        "pfad_fit_day_90_desc": ["de": "90 Tage. Du hast das Unmögliche möglich gemacht. Du bist ein Meister.", "en": "90 days. You have made the impossible possible. You are a master.", "es": "90 días. Has hecho posible lo imposible. Eres un maestro.", "fr": "90 jours. Tu as rendu l'impossible possible. Tu es un maître.", "it": "90 giorni. Hai reso possibile l'impossibile. Sei un maestro.", "pt": "90 dias. Fizeste o impossível possível. És um mestre."],
        "pfad_fit_phase_vertiefung_desc": ["de": "Vertiefe dein Training. Dein Körper wird noch stärker.", "en": "Deepen your training. Your body is getting even stronger.", "es": "Profundiza tu entrenamiento. Tu cuerpo se está volviendo aún más fuerte.", "fr": "Approfondis ton entraînement. Ton corps devient encore plus fort.", "it": "Approfondisci il tuo allenamento. Il tuo corpo sta diventando ancora più forte.", "pt": "Aprofunda o teu treino. O teu corpo está a ficar ainda mais forte."],
        "pfad_produktiv_phase_vertiefung_desc": ["de": "Meistere deine Zeit. Fokus wird zur Gewohnheit.", "en": "Master your time. Focus becomes a habit.", "es": "Domina tu tiempo. El enfoque se convierte en un hábito.", "fr": "Maîtrise ton temps. La concentration devient une habitude.", "it": "Padroneggia il tuo tempo. Il focus diventa un'abitudine.", "pt": "Domina o teu tempo. O foco torna-se um hábito."],
        "pfad_mental_phase_vertiefung_desc": ["de": "Innere Stärke kultivieren. Frieden findest du in dir.", "en": "Cultivate inner strength. You find peace within yourself.", "es": "Cultiva la fuerza interior. Encuentras la paz dentro de ti.", "fr": "Cultive ta force intérieure. Tu trouves la paix en toi-même.", "it": "Coltiva la forza interiore. Trovi la pace dentro di te.", "pt": "Cultiva a força interior. Encontras a paz dentro de ti."],
        "pfad_lernen_phase_vertiefung_desc": ["de": "Wissen vernetzen. Du lernst nun komplexe Zusammenhänge.", "en": "Network knowledge. You are now learning complex connections.", "es": "Conecta conocimientos. Ahora estás aprendiendo conexiones complejas.", "fr": "Réseautage des connaissances. Tu apprends maintenant des liens complexes.", "it": "Metti in rete le conoscenze. Ora stai imparando connessioni complesse.", "pt": "Conecta conhecimentos. Estás agora a aprender ligações complexas."],
        "pfad_gesund_phase_vertiefung_desc": ["de": "Gesundheit maximieren. Dein Körper dankt dir jeden Tag.", "en": "Maximize health. Your body thanks you every day.", "es": "Maximiza la salud. Tu cuerpo te lo agradece cada día.", "fr": "Maximise ta santé. Ton corps te remercie chaque jour.", "it": "Massimizza la salute. Il tuo corpo ti ringrazia ogni giorno.", "pt": "Maximiza a saúde. O teu corpo agradece-te todos os dias."],
        "pfad_fehlt_phase_vertiefung_desc": ["de": "Bleib dran an deinem Ziel. Du bist fast da.", "en": "Stay focused on your goal. You are almost there.", "es": "Mantente enfocado en tu meta. Casi estás ahí.", "fr": "Reste concentré sur ton objectif. Tu y es presque.", "it": "Rimani concentrato sul tuo obiettivo. Ci sei quasi.", "pt": "Mantém-te focado no teu objetivo. Estás quase lá."],
        "pfad_fit_phase_meisterschaft_desc": ["de": "Du bist ein Fitness-Profi. Halte dieses Level.", "en": "You are a fitness pro. Maintain this level.", "es": "Eres un pro del fitness. Mantén este nivel.", "fr": "Tu es un pro du fitness. Maintiens ce niveau.", "it": "Sei un professionista del fitness. Mantieni questo livello.", "pt": "És um pro de fitness. Mantém este nível."],
        "pfad_produktiv_phase_meisterschaft_desc": ["de": "Maximale Effizienz. Du beherrscht deinen Tag perfekt.", "en": "Maximum efficiency. You master your day perfectly.", "es": "Máxima eficiencia. Dominas tu día perfectamente.", "fr": "Efficacité maximale. Tu maîtrises parfaitement ta journée.", "it": "Massima efficienza. Padroneggi perfettamente la tua giornata.", "pt": "Eficiência máxima. Dominas o teu dia perfeitamente."],
        "pfad_mental_phase_meisterschaft_desc": ["de": "Tiefe Gelassenheit. Du bist eins mit dir selbst.", "en": "Deep serenity. You are at one with yourself.", "es": "Serenidad profunda. Eres uno contigo mismo.", "fr": "Sérénité profonde. Tu ne fais qu'un avec toi-même.", "it": "Profonda serenità. Sei in armonia con te stesso.", "pt": "Serenidade profunda. Estás em harmonia contigo mesmo."],
        "pfad_lernen_phase_meisterschaft_desc": ["de": "Lebenslanges Lernen. Wissen ist deine Superkraft.", "en": "Lifelong learning. Knowledge is your superpower.", "es": "Aprendizaje de por vida. El conocimiento es tu superpoder.", "fr": "Apprentissage tout au long de la vie. Le savoir est ton superpouvoir.", "it": "Apprendimento permanente. La conoscenza è il tuo superpotere.", "pt": "Aprendizagem ao longo da vida. O conhecimento é o teu superpoder."],
        "pfad_gesund_phase_meisterschaft_desc": ["de": "Goldener Status. Dein Körper ist dein Tempel.", "en": "Golden status. Your body is your temple.", "es": "Estado dorado. Tu cuerpo es tu templo.", "fr": "Statut doré. Ton corps est ton temple.", "it": "Status d'oro. Il tuo corpo è il tuo tempio.", "pt": "Estado de ouro. O teu corpo é o teu templo."],
        "pfad_fehlt_phase_meisterschaft_desc": ["de": "Ziel erreicht! Du hast bewiesen was in dir steckt.", "en": "Goal reached! You have proven what you are made of.", "es": "¡Meta alcanzada! Has demostrado de qué estás hecho.", "fr": "Objectif atteint ! Tu as prouvé de quoi tu es capable.", "it": "Obiettivo raggiunto! Hai dimostrato di che pasta sei fatto.", "pt": "Objetivo alcançado! Provaste do que és capaz."],
        "pfad_fehlt_phase_aufbau_desc": ["de": "Du machst Fortschritte. Steigere deinen persönlichen Einsatz heute.", "en": "You are making progress. Increase your personal effort today.", "es": "Estás progresando. Aumenta tu esfuerzo personal hoy.", "fr": "Tu fais des progrès. Augmente ton effort personnel aujourd'hui.", "it": "Stai facendo progressi. Aumenta il tuo impegno personale oggi.", "pt": "Estás a progredir. Aumenta o teu esforço pessoal hoje."],
        "pfad_phase_tag_titel_einstieg": ["de": "Einstieg", "en": "Entry", "es": "Inicio", "fr": "Début", "it": "Inizio", "pt": "Início"],
        "pfad_phase_tag_titel_aufbau": ["de": "Aufbau", "en": "Building", "es": "Construcción", "fr": "Construction", "it": "Costruzione", "pt": "Construção"],
        "pfad_phase_tag_titel_vertiefung": ["de": "Vertiefung", "en": "Refinement", "es": "Profundización", "fr": "Approfondissement", "it": "Approfondimento", "pt": "Aprofundamento"],
        "pfad_phase_tag_titel_meisterschaft": ["de": "Meisterschaft", "en": "Mastery", "es": "Maestría", "fr": "Maîtrise", "it": "Maestria", "pt": "Maestria"],
        "pfad_tag_header": ["de": "Tag %d", "en": "Day %d", "es": "Día %d", "fr": "Jour %d", "it": "Giorno %d", "pt": "Dia %d"],
        "pfad_tag_von": ["de": "Tag %d von %d", "en": "Day %d of %d", "es": "Día %d de %d", "fr": "Jour %d sur %d", "it": "Giorno %d di %d", "pt": "Dia %d de %d"],
        "pfad_erledigen_btn": ["de": "ERLEDIGEN", "en": "COMPLETE", "es": "COMPLETAR", "fr": "TERMINER", "it": "COMPLETA", "pt": "CONCLUIR"],
        "pfad_aktive_pflanzen": ["de": "Aktive Pflanzen", "en": "Active Plants", "es": "Plantas activas", "fr": "Plantes actives", "it": "Piante attive", "pt": "Plantas ativas"],
        "pfad_pflanze_kaufen": ["de": "Pflanze kaufen", "en": "Buy plant", "es": "Comprar planta", "fr": "Acheter une plante", "it": "Compra pianta", "pt": "Comprar planta"],
        "pfad_tag_verfuegbar_in": ["de": "Verfügbar in %@", "en": "Available in %@", "es": "Disponible en %@", "fr": "Disponible dans %@", "it": "Disponibile in %@", "pt": "Disponível em %@"],
        "pfad_done_prefix": ["de": "✓ %@", "en": "✓ %@", "es": "✓ %@", "fr": "✓ %@", "it": "✓ %@", "pt": "✓ %@"],
        "pfad_generic_description_fallback": ["de": "Bleib konzentriert auf deine Aufgabe: [HABIT]. Jeder Tag zählt auf deiner Reise.", "en": "Stay focused on your task: [HABIT]. Every day counts on your journey.", "es": "Mantente enfocado en tu tarea: [HABIT]. Cada día cuenta en tu viaje.", "fr": "Reste concentré sur ta tâche : [HABIT]. Chaque jour compte dans ton voyage.", "it": "Resta concentrato sul tuo compito: [HABIT]. Ogni giorno conta nel tuo viaggio.", "pt": "Mantém o foco na tua tarefa: [HABIT]. Cada dia conta na tua jornada."],
        "pfad_progress_format": ["de": "Tag %d / 90", "en": "Day %d / 90", "es": "Día %d / 90", "fr": "Jour %d / 90", "it": "Giorno %d / 90", "pt": "Dia %d / 90"],
        "pfad_mental_day_7_title": ["de": "Eine Woche Achtsamkeit", "en": "One Week of Mindfulness", "es": "Una semana de atención plena", "fr": "Une semaine de pleine conscience", "it": "Una settimana di consapevolezza", "pt": "Uma semana de consciência"],
        "pfad_mental_day_7_desc": ["de": "Du hast 7 Tage lang bewusst geatmet. Spürst du die Ruhe?", "en": "You have breathed consciously for 7 days. Do you feel the peace?", "es": "Has respirado conscientemente durante 7 días. ¿Sientes la paz?", "fr": "Tu as respiré consciemment pendant 7 jours. Sens-tu le calme ?", "it": "Hai respirato consapevolmente per 7 giorni. Senti la pace?", "pt": "Respiraste conscientemente durante 7 dias. Sentes a paz?"],
        "pfad_lernen_day_7_title": ["de": "Wissens-Woche", "en": "Knowledge Week", "es": "Semana del conocimiento", "fr": "Semaine du savoir", "it": "Settimana della conoscenza", "pt": "Semana do conhecimento"],
        "pfad_lernen_day_7_desc": ["de": "Ganze 7 Tage Lesen. Dein Wissen wächst wie dein Garten.", "en": "A full 7 days of reading. Your knowledge grows like your garden.", "es": "7 días enteros de lectura. Tu conocimiento crece como tu jardín.", "fr": "7 jours entiers de lecture. Ton savoir grandit comme ton jardin.", "it": "Interi 7 giorni di lettura. La tua conoscenza cresce come il tuo giardino.", "pt": "7 dias inteiros de leitura. O teu conhecimento cresce como o teu jardim."],
        "pfad_gesund_day_7_title": ["de": "Hydrierungs-Profi", "en": "Hydration Pro", "es": "Pro de la hidratación", "fr": "Pro de l'hydratation", "it": "Pro dell'idratazione", "pt": "Pro da hidratação"],
