        "item.zauberstab.name": ["de": "Zauberstab", "en": "Magic Wand", "es": "Varita Mágica", "fr": "Baguette magique", "it": "Bacchetta magica", "pt": "Varinha mágica"],
        "item.zauberstab.usage": ["de": "Wird sofort aktiv und lässt Unkraut wie von Geisterhand verschwinden.", "en": "Becomes active immediately and makes weeds disappear as if by magic.", "es": "Se activa de inmediato y hace desaparecer las malas hierbas como por arte de magia.", "fr": "S\'active immédiatement et fait disparaître les mauvaises herbes comme par enchantement.", "it": "Si attiva immediatamente e fa sparire le erbacce come per magia.", "pt": "Ativa imediatamente e faz as ervas daninhas desaparecer como por magia."],
        "item.zeitkapsel.description": ["de": "Friert eine Pflanze ein – kein Verfall für 3 Tage.", "en": "Freezes a plant – no decay for 3 days.", "es": "Congela una planta – sin deterioro durante 3 días.", "fr": "Gèle une plante – pas de dégradation pendant 3 jours.", "it": "Congela una pianta – senza decomposizione per 3 giorni.", "pt": "Congela uma planta – sem degradação durante 3 dias."],
        "item.zeitkapsel.name": ["de": "Zeitkapsel", "en": "Time Capsule", "es": "Cápsula del Tiempo", "fr": "Capsule temporelle", "it": "Capsula del tempo", "pt": "Cápsula do tempo"],
        "item.zeitkapsel.usage": ["de": "Wird sofort aktiv und stoppt den Verfall aller Pflanzen.", "en": "Becomes active immediately and stops decay for all plants.", "es": "Wird sofort aktiv und stoppt den Verfall aller Pflanzen.", "fr": "S'active immédiatement et stoppe la dégradation de toutes les plantes.", "it": "Diventa attivo immediatamente e blocca la decomposizione di tutte le piante.", "pt": "Ativa imediatamente e para a degradação de todas as plantas."],
