        "onboarding_benachrichtigung_blase": ["de": "Soll ich dich an deine Gewohnheiten erinnern? So vergisst du nie zu gießen!", "en": "Should I remind you of your habits? That way you'll never forget to water!", "es": "¿Quieres que te recuerde tus hábitos? ¡Así nunca olvidarás regar!", "fr": "Dois-je te rappeler tes habitudes ? Ainsi, tu n'oublieras jamais d'arroser !", "it": "Dovrei ricordarti le tue abitudini? In questo modo non ti dimenticherai mai di annaffiare!", "pt": "Queres que te lembre dos teus hábitos? Assim nunca te esquecerás de regar!"],
        "onboarding_benachrichtigung_einstellungen": ["de": "In Einstellungen öffnen", "en": "Open in Settings", "es": "Abrir en Ajustes", "fr": "Ouvrir les paramètres", "it": "Apri in Impostazioni", "pt": "Abrir nas Definições"],
        "onboarding_benachrichtigung_erlauben": ["de": "ERLAUBEN", "en": "ALLOW", "es": "PERMITIR", "fr": "AUTORISER", "it": "PERMETTERE", "pt": "PERMITIR"],
        "onboarding_benachrichtigung_spaeter": ["de": "Später vielleicht", "en": "Maybe later", "es": "Tal vez más tarde", "fr": "Plus tard peut-être", "it": "Forse più tardi", "pt": "Talvez mais tarde"],
        "notification.evening.1.body": ["de": "Du hast noch %d %@! Komm vorbei, bevor der Tag endet.", "en": "You still have %d %@! Stop by before the day ends.", "es": "¡Aún tienes %d %@! Pasa por aquí antes de que acabe el día.", "fr": "Tu as encore %d %@ ! Viens avant la fin de la journée.", "it": "Hai ancora %d %@! Passa prima che finisca la giornata.", "pt": "Ainda tens %d %@! Aparece antes que o dia acabe."],
        "notification.evening.1.title": ["de": "Dein Garten wartet", "en": "Your garden is waiting", "es": "Tu jardín te espera", "fr": "Ton jardin t'attend", "it": "Il tuo giardino ti aspetta", "pt": "O teu jardim espera por ti"],
        "notification.evening.2.body": ["de": "Vergiss nicht auf deine Pflanzen! %d %@ braucht heute noch Wasser.", "en": "Don't forget your plants! %d %@ still needs water today.", "es": "¡No olvides tus plantas! %d %@ todavía necesita agua hoy.", "fr": "N'oublie pas tes plantes ! %d %@ a encore besoin d'eau aujourd'hui.", "it": "Non dimenticare le tue piante! %d %@ ha ancora bisogno d'acqua oggi.", "pt": "Não te esqueças das tuas plantas! %d %@ ainda precisa de água hoje."],
        "notification.evening.2.title": ["de": "Ein letzter Blick?", "en": "One last look?", "es": "¿Un último vistazo?", "fr": "Un dernier coup d'œil ?", "it": "Un'ultima occhiata?", "pt": "Um último olhar?"],
        "notification.evening.3.body": ["de": "Der Abend bricht an... und %d %@ rufen nach dir!", "en": "Evening falls... and %d %@ are calling for you!", "es": "Cae la noche... ¡y %d %@ te están llamando!", "fr": "Le soir tombe... et %d %@ t'appellent !", "it": "Scende la sera... e %d %@ ti chiamano!", "pt": "A noite cai... e %d %@ chamam por ti!"],
        "notification.evening.3.title": ["de": "Stille im Garten", "en": "Silence in the garden", "es": "Silencio en el jardín", "fr": "Silence dans le jardin", "it": "Silenzio nel giardino", "pt": "Silêncio no jardim"],
        "notification.morning.1.body": ["de": "Zeit für Gewohnheiten! Dein höchster Streak ist %d. Lass uns weiter wachsen!", "en": "Time for habits! Your highest streak is %d. Let's keep growing!", "es": "¡Hora de los hábitos! Tu mejor racha es %d. ¡Sigamos creciendo!", "fr": "L'heure des habitudes ! Ta meilleure série est %d. Continuons à grandir !", "it": "È l'ora delle abitudini! La tua serie migliore è %d. Continuiamo a crescere!", "pt": "Hora dos hábitos! O teu melhor streak é %d. Vamos continuar a crescer!"],
        "notification.morning.1.title": ["de": "Guten Morgen!", "en": "Good morning!", "es": "¡Buenos días!", "fr": "Bonjour !", "it": "Buongiorno!", "pt": "Bom dia!"],
        "notification.morning.2.body": ["de": "Ein neuer Start! Baue deinen Streak von %d weiter aus.", "en": "A fresh start! Keep building your streak of %d.", "es": "¡Un nuevo comienzo! Sigue aumentando tu racha de %d.", "fr": "Un nouveau départ ! Continue de construire ta série de %d.", "it": "Un nuovo inizio! Continua a costruire la tua serie di %d.", "pt": "Um novo começo! Continua a aumentar o teu streak de %d."],
        "notification.morning.2.title": ["de": "Erfrischt aufwachen", "en": "Wake up refreshed", "es": "Despierta con energía", "fr": "Réveille-toi en forme", "it": "Svegliati rinfrescato", "pt": "Acorda revigorado"],
        "notification.morning.3.body": ["de": "Dein Garten gedeiht! %d Tage harte Arbeit warten auf Fortsetzung.", "en": "Your garden thrives! %d days of hard work await continuation.", "es": "¡Tu jardín prospera! %d días de duro trabajo esperan continuar.", "fr": "Ton jardin prospère ! %d jours de dur labeur t'attendent.", "it": "Il tuo giardino prospera! %d giorni di duro lavoro aspettano di essere continuati.", "pt": "O teu jardim prospera! %d dias de trabalho árduo aguardam continuação."],
        "notification.morning.3.title": ["de": "Neuer Tag, neues Glück", "en": "New day, new luck", "es": "Nuevo día, nueva suerte", "fr": "Nouveau jour, nouvelle chance", "it": "Nuovo giorno, nuova fortuna", "pt": "Novo dia, nova sorte"],
        "notification.streak.1.body": ["de": "Ohje! Wenn du jetzt nachlässt, stirbt die Pflanze und du verlierst %d Tage Streak.", "en": "Oh dear! If you slack now, the plant dies and you lose a %d-day streak.", "es": "¡Oh no! Si aflojas ahora, la planta muere y pierdes una racha de %d días.", "fr": "Oh là là ! Si tu relâches maintenant, la plante meurt et tu perds %d jours de série.", "it": "Oh no! Se ti arrendi ora, la pianta muore e perdi %d giorni di serie.", "pt": "Oh não! Se vacilares agora, a planta morre e perdes um streak de %d dias."],
        "notification.streak.1.title": ["de": "Achtung, Streak in Gefahr!", "en": "Watch out, streak in danger!", "es": "¡Cuidado, racha en peligro!", "fr": "Attention, série en danger !", "it": "Attenzione, serie in pericolo!", "pt": "Cuidado, streak em perigo!"],
        "notification.streak.2.body": ["de": "Deine Gewohnheit steht auf der Kippe. Rette jetzt deine %d-Tage harte Arbeit!", "en": "Your habit is on the brink. Save your %d days of hard work now!", "es": "Tu hábito está en peligro. ¡Salva ahora tus %d días de duro trabajo!", "fr": "Ton habitude est en péril. Sauve maintenant tes %d jours de dur labeur !", "it": "La tua abitudine è a rischio. Salva ora i tuoi %d giorni di duro lavoro!", "pt": "O teu hábito corre perigo. Salva agora os teus %d dias de trabalho árduo!"],
        "notification.streak.2.title": ["de": "%@ welkt gleich...", "en": "%@ is about to wither...", "es": "%@ está a punto de marchitarse...", "fr": "%@ est sur le point de faner...", "it": "%@ sta per appassire...", "pt": "%@ está quase a murchar..."],
        "notification.streak.3.body": ["de": "Du bist schon %d Tage dabei! Lass es nicht umsonst gewesen sein.", "en": "You've been at it for %d days! Don't let it be for nothing.", "es": "¡Llevas %d días en esto! No dejes que sea en vano.", "fr": "Ça fait déjà %d jours ! Ne laisse pas ça être pour rien.", "it": "Sei già a %d giorni! Non far sì che sia tutto inutile.", "pt": "Já estás nisto há %d dias! Não deixes que seja em vão."],
        "notification.streak.3.title": ["de": "Bleib dran für %@!", "en": "Keep it up for %@!", "es": "¡Sigue así por %@!", "fr": "Continue pour %@ !", "it": "Continua così per %@!", "pt": "Continua por %@!"],
        "notification.wait.1.body": ["de": "Schon %d Stunden ohne Pflege. Schau doch kurz im Garten vorbei!", "en": "Already %d hours without care. Just drop by the garden briefly!", "es": "Ya van %d horas sin cuidados. ¡Pasa un momento por el jardín!", "fr": "Déjà %d heures sans soins. Fais un petit tour dans le jardin !", "it": "Già %d ore senza cure. Fai un salto nel giardino!", "pt": "Já %d horas sem cuidados. Dá um salto ao jardim!"],
        "notification.wait.1.title": ["de": "%@ vermisst dich!", "en": "%@ misses you!", "es": "¡%@ te echa de menos!", "fr": "%@ s'ennuie de toi !", "it": "%@ sente la tua mancanza!", "pt": "%@ tem saudades tuas!"],
        "notification.wait.2.body": ["de": "Die Zeit rennt! Erledige deine Gewohnheit (%d Stunden vergangen).", "en": "Time is flying! Complete your habit (%d hours passed).", "es": "¡El tiempo vuela! Completa tu hábito (han pasado %d horas).", "fr": "Le temps file ! Complète ton habitude (%d heures écoulées).", "it": "Il tempo vola! Completa la tua abitudine (%d ore passate).", "pt": "O tempo voa! Completa o teu hábito (%d horas passadas)."],
        "notification.wait.2.title": ["de": "Hallo? Zeit für %@!", "en": "Hello? Time for %@!", "es": "¿Hola? ¡Hora de %@!", "fr": "Allô ? C'est l'heure de %@ !", "it": "Ciao? È l'ora di %@!", "pt": "Olá? Hora de %@!"],
        "notification.wait.3.body": ["de": "Du hast noch %d Stunden Zeit, dich um deine Pflanze zu kümmern.", "en": "You have %d hours left to take care of your plant.", "es": "Aún tienes %d horas para cuidar de tu planta.", "fr": "Il te reste %d heures pour t'occuper de ta plante.", "it": "Hai ancora %d ore per prenderti cura della tua pianta.", "pt": "Ainda tens %d horas para cuidar da tua planta."],
        "notification.wait.3.title": ["de": "Vergiss \"%@\" nicht!", "en": "Don't forget \"%@\"! ", "es": "¡No olvides \"%@\"! ", "fr": "N'oublie pas \"%@\" ! ", "it": "Non dimenticare \"%@\"! ", "pt": "Não te esqueças de \"%@\"! "],
        "onboarding_benachrichtigung_status_abgelehnt": ["de": "Hinweis: Du hast Mitteilungen bereits deaktiviert. Um sie zu nutzen, musst du sie in den iOS-Einstellungen aktivieren.", "en": "Note: You have already disabled notifications. To use them, you must re-enable them in the iOS settings.", "es": "Nota: Ya has desactivado las notificaciones. Para usarlas, debes volver a activarlas en los ajustes de iOS.", "fr": "Note : tu as déjà désactivé les notifications. Pour les utiliser, tu dois les réactiver dans les réglages iOS.", "it": "Nota: hai già disabilitato le notifiche. Per utilizzarli è necessario riattivarli nelle impostazioni di iOS.", "pt": "Nota: Já desativaste as notificações. Para as usares, tens de as reativar nas definições do iOS."],
        "onboarding_benachrichtigung_text": ["de": "Aktiviere Mitteilungen, um deinen Garten am Leben zu erhalten.", "en": "Enable notifications to keep your garden alive.", "es": "Activa las notificaciones para mantener vivo tu jardín.", "fr": "Active les notifications pour garder ton jardin en vie.", "it": "Abilita le notifiche per mantenere vivo il tuo giardino.", "pt": "Ativa as notificações para manter o teu jardim vivo."],
        "onboarding_benachrichtigung_titel": ["de": "Erinnerungen", "en": "Reminders", "es": "Recordatorios", "fr": "Rappels", "it": "Promemoria", "pt": "Lembretes"],
        "onboarding_fertig_blase": ["de": "Dein Garten ist bereit! Viel Erfolg beim Wachsen deiner neuen Gewohnheiten.", "en": "Your garden is ready! Good luck growing your new habits.", "es": "¡Tu jardín está listo! Buena suerte cultivando tus nuevos hábitos.", "fr": "Ton jardin est prêt ! Bonne chance pour faire grandir tes nouvelles habitudes.", "it": "Il tuo giardino è pronto! Buona fortuna per far crescere le tue nuove abitudini.", "pt": "O teu jardim está pronto! Boa sorte a cultivar os teus novos hábitos."],
        "onboarding_fertig_button": ["de": "GARTEN ÖFFNEN", "en": "OPEN GARDEN", "es": "ABRIR JARDÍN", "fr": "OUVRIR LE JARDIN", "it": "GIARDINO APERTO", "pt": "ABRIR JARDIM"],
        "onboarding_fertig_startcoins": ["de": "50 Start-Coins erhalten", "en": "Received 50 start coins", "es": "Recibidas 50 monedas de inicio", "fr": "Reçu 50 pièces de départ", "it": "Hai ricevuto 50 monete iniziali", "pt": "Recebeste 50 moedas iniciais"],
        "onboarding_fertig_titel": ["de": "Alles bereit!", "en": "All ready!", "es": "¡Todo listo!", "fr": "Tout est prêt !", "it": "Tutto pronto!", "pt": "Tudo pronto!"],
        "onboarding_los_gehts": ["de": "LOS GEHT'S", "en": "LET'S GO", "es": "¡VAMOS!", "fr": "C'EST PARTI", "it": "ANDIAMO", "pt": "VAMOS LÁ"],
        "onboarding_pflanzen_blase": ["de": "Such dir zwei Pflanzen aus, die du heute pflanzen möchtest.", "en": "Pick two plants you'd like to plant today.", "es": "Elige dos plantas que te gustaría plantar hoy.", "fr": "Choisis deux plantes que tu aimerais planter aujourd'hui.", "it": "Scegli due piante che vorresti piantare oggi.", "pt": "Escolhe duas plantas que gostarias de plantar hoje."],
        "onboarding_pflanzen_hinweis": ["de": "Wähle genau 2 Pflanzen", "en": "Select exactly 2 plants", "es": "Selecciona exactamente 2 plantas", "fr": "Choisis exactement 2 plantes", "it": "Seleziona esattamente 2 piante", "pt": "Seleciona exatamente 2 plantas"],
        "onboarding_pflanzen_weiter": ["de": "WEITER", "en": "CONTINUE", "es": "CONTINUAR", "fr": "CONTINUER", "it": "CONTINUA", "pt": "CONTINUAR"],
        "onboarding_shop_blase": ["de": "Im Shop findest du neue Pflanzen und nützliche Gegenstände für deine Reise.", "en": "In the shop, you'll find new plants and useful items for your journey.", "es": "En la tienda encontrarás nuevas plantas y objetos útiles para tu viaje.", "fr": "Dans la boutique, tu trouveras de nouvelles plantes et des objets utiles pour ton voyage.", "it": "Nel negozio troverai nuove piante e oggetti utili per il tuo viaggio.", "pt": "Na loja, encontrarás novas plantas e itens úteis para a tua viagem."],
        "onboarding_tutorial_1_text": ["de": "Erledige deine Gewohnheit und tippe auf den Wassertropfen.", "en": "Complete your habit and tap the water drop.", "es": "Completa tu hábito y toca la gota de agua.", "fr": "Complète ton habitude et appuie sur la goutte d'eau.", "it": "Completa la tua abitudine e tocca la goccia d'acqua.", "pt": "Completa o teu hábito e toca na gota de água."],
        "onboarding_tutorial_1_titel": ["de": "Gieße täglich", "en": "Water daily", "es": "Riega a diario", "fr": "Arrose tous les jours", "it": "Innaffiare ogni giorno", "pt": "Rega todos os dias"],
        "onboarding_tutorial_2_text": ["de": "Deine Pflanzen wachsen von Bronze bis Diamant.", "en": "Your plants grow from Bronze to Diamond.", "es": "Tus plantas crecen de bronce a diamante.", "fr": "Tes plantes poussent de Bronze à Diamant.", "it": "Le tue piante crescono dal Bronzo al Diamante.", "pt": "As tuas plantas crescem de Bronze a Diamante."],
        "onboarding_tutorial_2_titel": ["de": "Sammle XP", "en": "Collect XP", "es": "Colecciona XP", "fr": "Collecte de l'XP", "it": "Raccogli XP", "pt": "Coleciona XP"],
        "onboarding_tutorial_3_text": ["de": "Verdiene Coins und kaufe neue Pflanzen & Gegenstände.", "en": "Earn coins and buy new plants & items.", "es": "Gana monedas y compra nuevas plantas y objetos.", "fr": "Gagne des pièces et achète de nouvelles plantes et objets.", "it": "Guadagna monete e acquista nuove piante e oggetti.", "pt": "Ganha moedas e compra novas plantas e itens."],
        "onboarding_tutorial_3_titel": ["de": "Kaufe im Shop", "en": "Buy in the Shop", "es": "Compra en la tienda", "fr": "Achète dans la boutique", "it": "Acquista nel Negozio", "pt": "Compra na loja"],
        "onboarding_tutorial_4_text": ["de": "Schlechte Gewohnheiten geben dir kurzfristige Boni, aber nutze sie weise!", "en": "Bad Habits give you short-term bonuses, but use them wisely!", "es": "Las decoraciones te dan bonos a corto plazo, ¡pero úsalas con sabiduría!", "fr": "Les décorations te donnent des bonus à court terme, mais utilise-les avec sagesse !", "it": "Le decorazioni ti danno bonus a breve termine, ma usale con saggezza!", "pt": "As decorações dão-te bónus a curto prazo, mas usa-as com sabedoria!"],
        "onboarding_tutorial_4_titel": ["de": "Deko & Belohnung", "en": "Bad Habits & Rewards", "es": "Decoraciones y recompensas", "fr": "Décorations et récompenses", "it": "Decorazioni e ricompense", "pt": "Decorações e recompensas"],
        "onboarding_tutorial_5_text": ["de": "Gegenstände lassen Unkraut wachsen, das XP und Fortschritt blockiert.", "en": "Items can cause weeds to grow, hindering XP and progress.", "es": "Los objetos pueden hacer que crezcann malas hierbas, lo que dificulta la XP.", "fr": "Les objets peuvent faire de l'herbe pousse, ce qui freine l'XP.", "it": "Oggetti possono far crescere le erbacce, ostacolando l'XP.", "pt": "Os itens podem causar ervas daninhas, dificultando o XP."],
        "onboarding_tutorial_5_titel": ["de": "Achtung vor Unkraut!", "en": "Beware of Weeds!", "es": "¡Cuidado mit Unkraut!", "fr": "Attention aux mauvaises herbes !", "it": "Attenzione alle erbacce!", "pt": "Cuidado com as ervas daninhas!"],
        "onboarding_tutorial_blase": ["de": "So funktioniert dein Garten!", "en": "This is how your garden works!", "es": "¡Así funciona tu jardín!", "fr": "Voici comment fonctionne ton jardin !", "it": "Ecco come funktioniert il tuo giardino!", "pt": "É assim que o teu jardim funciona!"],
        "onboarding_tutorial_giessen_blase": ["de": "Zieh den Wassertropfen auf die Pflanze, um sie zu gießen!", "en": "Drag the water drop onto the plant to water it!", "es": "¡Arrastra la gota de agua a la planta para regarla!", "fr": "Fais glisser la goutte d'eau sur la plante pour l'arroser !", "it": "Trascina la goccia d'acqua sulla pianta per annaffiarla!", "pt": "Arrasta a gota de água para a planta para a regares!"],
        "onboarding_tutorial_giessen_erfolg": ["de": "Klasse! So pflegst du deine Gewohnheiten.", "en": "Great! This is how you nurture your habits.", "es": "¡Genial! Así es como cuidas tus hábitos.", "fr": "Génial ! C'est ainsi que tu cultives tes habitudes.", "it": "Grande! È così che coltivi le tue abitudini.", "pt": "Espetacular! É assim que nutres os teus hábitos."],
        "onboarding_tutorial_giessen_test": ["de": "Deine erste Pflanze", "en": "Your first plant", "es": "Tu primera planta", "fr": "Ta première plante", "it": "La tua prima pianta", "pt": "A tua primeira planta"],
        "onboarding_tutorial_interactive_shop_bubble": ["de": "Im Shop kannst du deine Coins gegen tolle Gegenstände eintauschen!", "en": "In the shop, you can exchange your coins for great items!", "es": "¡En la tienda puedes canjear tus monedas por objetos geniales!", "fr": "Dans la boutique, tu peux échanger tes pièces contre de superbes objets !", "it": "Nel negozio puoi scambiare le tue monete con fantastici oggetti!", "pt": "Na loja, podes trocar as tuas moedas por itens incríveis!"],
        "onboarding_tutorial_interactive_shop_buy": ["de": "Kauf dir mal diesen Dünger!", "en": "Go ahead and buy this fertilizer!", "es": "¡Cómprate este fertilizante!", "fr": "Achète cet engrais !", "it": "Vai avanti e acquista questo fertilizzante!", "pt": "Compra este fertilizante!"],
        "onboarding_tutorial_interactive_shop_success": ["de": "Stark! Items geben dir sofortige Vorteile im Garten.", "en": "Awesome! Items give you immediate benefits in the garden.", "es": "¡Genial! Los objetos te dan beneficios inmediatos en el jardín.", "fr": "Génial ! Les objets te procurent des avantages immédiats dans le jardin.", "it": "Eccezionale! Gli articoli ti danno benefici immediati in giardino.", "pt": "Incrível! Os itens dão-te benefícios imediatos no jardim."],
        "onboarding_tutorial_powerup_bubble": ["de": "Ich gebe dir verschiedene Effekte für den Garten. Benutze sie um schöne Fortschritte zu erreichen.", "en": "I'll give you various effects for the garden. Use them to make beautiful progress.", "es": "Te daré varios efectos para el jardín. Úsalos para lograr un progreso hermoso.", "fr": "Je vais te donner divers effets pour le jardin. Utilise-les pour faire de beaux progrès.", "it": "Ti darò vari effetti per il giardino. Usali per fare bei progressi.", "pt": "Vou dar-te vários efeitos para o jardim. Usa-os para fazeres belos progressos."],
        "onboarding_tutorial_powerup_detail_hint": ["de": "Tippe auf den Schlüssel, um ihn einzusetzen!", "en": "Tap the key to use it!", "es": "¡Toca la llave para usarla!", "fr": "Appuie sur la clé pour l'utiliser !", "it": "Tocca la chiave per usarla!", "pt": "Tocca na chave para a usares!"],
        "onboarding_tutorial_powerup_active_success": ["de": "Stark! Der Goldene Schlüssel ist nun aktiv. Du erhältst jetzt 1.5x mehr XP!", "en": "Awesome! The Golden Key is now active. You now get 1.5x more XP!", "es": "¡Genial! La Llave Dorada está activa. ¡Ahora obtienes 1.5x más XP!", "fr": "Super ! La Clé Dorée est maintenant active. Tu reçois maintenant 1.5x plus d'XP !", "it": "Ottimo! La Chiave Dorata è ora attiva. Ricevi ora 1.5x più XP!", "pt": "Incrível! A Chave Dourada está agora ativa. Recebes agora 1.5x mais XP!"],
        "onboarding_tutorial_interactive_weed_bubble": ["de": "Unkraut macht deinen Garten schwächer und du verdienst weniger XP! Vermeide es, indem du nicht zu viele Schlechte Gewohnheiten kaufst.", "en": "Weeds make your garden weaker and you earn less XP! Avoid them by not buying too many decorations.", "es": "¡Las malas hierbas debilitan tu jardín y ganas menos XP! Evítalas no comprando demasiadas decoraciones.", "fr": "Les mauvaises herbes affaiblissent ton jardin et tu gagnes moins d'XP ! Évite-les en n'achetant pas trop de décorations.", "it": "Le erbacce indeboliscono il tuo giardino e guadagni meno XP! Evitale non comprando troppe decorazioni.", "pt": "As ervas daninhas enfraquecem o teu jardim e ganhas menos XP! Evita-as não comprando demasiadas decorações."],
        "onboarding_tutorial_interactive_weed_warning": ["de": "Schlechte Gewohnheiten locken langfristig Unkraut an. Je mehr Deko, desto höher die Gefahr im Glücksrad!", "en": "Bad Habits attract weeds in the long run. The more deco, the higher the danger in the wheel!", "es": "Las decoraciones atraen malas hierbas a largo plazo. ¡A más decoración, mayor peligro en la ruleta!", "fr": "Les décorations attirent les mauvaises herbes à long terme. Plus il y a de déco, plus le danger est grand dans la roue !", "it": "Le decorazioni attraggono le erbacce a lungo termine. Più decorazioni ci sono, maggiore è il pericolo nella ruota!", "pt": "As decorações atraem ervas daninhas a longo prazo. Quanto mais decoração, maior o perigo na roleta!"],
        "onboarding_tutorial_interactive_xp_bubble": ["de": "Tippe auf die Pflanze oben, um sie zu gießen und XP zu sammeln!", "en": "Tap the plant above to water it and collect XP!", "es": "¡Toca la planta arriba para regarla y ganar XP!", "fr": "Appuie sur la plante ci-dessus pour l'arroser et gagner de l'XP !", "it": "Tocca la pianta in alto per annaffiarla e raccogliere XP!", "pt": "Toca na planta acima para a regares e ganhares XP!"],
        "onboarding_tutorial_interactive_xp_success": ["de": "Super! Wenn der Ring voll ist, steigt deine Pflanze ein Level auf.", "en": "Great! When the ring is full, your plant levels up.", "es": "¡Genial! Quando el círculo esté lleno, tu planta subirá de nivel.", "fr": "Super ! Quand l'anneau est plein, ta plante monte de niveau.", "it": "Grande! Quando l'anello è pieno, la tua pianta sale di livello.", "pt": "Espetacular! Quando o anel estiver cheio, a tua planta sobe de nível."],
        "onboarding_tutorial_xp_goal": ["de": "DEIN ZIEL", "en": "YOUR GOAL", "es": "TU OBJETIVO", "fr": "TON OBJECTIF", "it": "IL TUO OBIETTIVO", "pt": "O TEU OBJETIVO"],
        "onboarding_tutorial_xp_success_final": ["de": "You go!", "en": "You go!", "es": "¡Tú puedes!", "fr": "C'est parti !", "it": "Tu vai!", "pt": "Tu consegues!"],
        "onboarding_tutorial_weed_decoration_hint": ["de": "Kauf dir eine Deko für schnelle Boni!", "en": "Buy a decoration for quick bonuses!", "es": "¡Compra una decoración para obtener bonos rápidos!", "fr": "Achète une décoration pour des bonus rapides !", "it": "Compra una decorazione per dei bonus rapidi!", "pt": "Compra uma decoração para bónus rápidos!"],
        "onboarding_weiter": ["de": "WEITER", "en": "CONTINUE", "es": "CONTINUAR", "fr": "CONTINUER", "it": "CONTINUA", "pt": "CONTINUAR"],
        "onboarding_willkommen_blase": ["de": "Hallo! Ich bin dein Garten-Guide. Lass uns zusammen deinen persönlichen Garten anlegen!", "en": "Hello! I'm your garden guide. Let's create your personal garden together!", "es": "¡Hola! Soy tu guía del jardín. ¡Curemos juntos tu jardín personal!", "fr": "Bonjour ! Je suis ton guide du jardin. Créons ton jardin personnel ensemble !", "it": "Ciao! Sono la tua guida del giardino. Realizziamo insieme il tuo giardino personale!", "pt": "Olá! Sou o teu guia do jardim. Vamos criar o teu jardim pessoal juntos!"],
        "onboarding_willkommen_titel": ["de": "Willkommen im Garten", "en": "Welcome to the Garden", "es": "Bienvenido al Jardín", "fr": "Bienvenue dans le jardin", "it": "Benvenuti al Giardino", "pt": "Bem-vindo ao Jardim"],
        "onboarding_willkommen_untertitel": ["de": "Baue Gewohnheiten auf, die wachsen.", "en": "Build habits that grow.", "es": "Crea hábitos que crezcan.", "fr": "Crée des habitudes qui grandissent.", "it": "Costruisci abitudini che crescono.", "pt": "Cria hábitos que cresçam."],
        "onboarding_xp_blase": ["de": "Mit jedem Gießen sammelst du XP. Deine Pflanzen wachsen von Bronze bis Diamant!", "en": "With every watering, you collect XP. Your plants grow from Bronze to Diamond!", "es": "Con cada riego, coleccionas XP. ¡Tus plantas crecen de bronce a diamante!", "fr": "À chaque arrosage, tu collectes de l'XP. Tes plantes poussent de Bronze à Diamant !", "it": "Ad ogni irrigazione raccogli XP. Le tue piante crescono dal Bronzo al Diamante!", "pt": "Com cada rega, recolhes XP. As tuas plantas crescem de Bronze a Diamante!"],
        "onboarding_zeit_blase": ["de": "Wann möchtest du deine Gewohnheiten erledigen?", "en": "When do you want to do your habits?", "es": "¿Cuándo quieres realizar tus hábitos?", "fr": "Quand veux-tu accomplir tes habitudes ?", "it": "Quando vuoi fare le tue abitudini?", "pt": "Quando queres realizar os teus hábitos?"],
        "onboarding_zeit_blase_personal": ["de": "Wann möchtest du an %@ erinnert werden?", "en": "When do you want to be reminded of %@?", "es": "¿Cuándo quieres que se te recuerde %@?", "fr": "Quand veux-tu qu'on te rappelle %@ ?", "it": "Quando vuoi che ti venga ricordato %@?", "pt": "Quando queres ser lembrado de %@?"],
        "onboarding_zeit_progress": ["de": "Schritt %d von %d", "en": "Step %d of %d", "es": "Paso %d de %d", "fr": "Étape %d sur %d", "it": "Passaggio %d di %d", "pt": "Passo %d de %d"],
        "onboarding_zeit_erklaerung": ["de": "Du bekommst täglich eine Erinnerung zu dieser Zeit.", "en": "You will receive a daily reminder at this time.", "es": "Recibirás un recordatorio diario a esta hora.", "fr": "Tu recevras un rappel quotidien à cette heure.", "it": "Riceverai un promemoria giornaliero in questo momento.", "pt": "Receberás um lembrete diário a esta hora."],
        "onboarding_zeit_erklaerung_personal": ["de": "Du bekommst täglich eine Erinnerung für diese Pflanze.", "en": "You will receive a daily reminder for this plant.", "es": "Recibirás un recordatorio diario para esta planta.", "fr": "Tu recevras un rappel quotidien pour cette plante.", "it": "Riceverai un promemoria giornaliero per questa pianta.", "pt": "Receberás um lembrete diário para esta planta."],
        "onboarding_zeit_weiter": ["de": "WEITER", "en": "CONTINUE", "es": "CONTINUAR", "fr": "CONTINUER", "it": "CONTINUA", "pt": "CONTINUAR"],
        "onboarding_custom_blase": ["de": "Gib deinen eigenen Gewohnheiten einen Namen!", "en": "Give your own habits a name!", "es": "¡Nombra tus propios hábitos!", "fr": "Donne un nom à tes propres habitudes !", "it": "Dai un nome alle tue abitudini!", "pt": "Dá um nome aos teus próprios hábitos!"],
        "onboarding_custom_add": ["de": "Gewohnheit hinzufügen", "en": "Add Habit", "es": "Añadir hábito", "fr": "Ajouter une habitude", "it": "Aggiungi abitudine", "pt": "Adicionar hábito"],
        "onboarding_custom_title": ["de": "Eigene Gewohnheit", "en": "Own Habit", "es": "Propio hábito", "fr": "Propre habitude", "it": "Propria abitudine", "pt": "Hábito próprio"],
