        "streak.motivation.1": ["de": "Jeden Tag ein kleines Stück besser.", "en": "A little better every single day.", "es": "Cada día un poco mejor.", "fr": "Un peu mieux chaque jour.", "it": "Un po' meglio ogni singolo giorno.", "pt": "Um pouco melhor a cada dia."],
        "streak.motivation.2": ["de": "Dranbleiben zahlt sich aus!", "en": "Consistency pays off!", "es": "¡La constancia tiene su recompensa!", "fr": "La constance paie !", "it": "La coerenza ripaga!", "pt": "A consistência compensa!"],
        "streak.motivation.3": ["de": "Du bist stärker als du denkst.", "en": "You are stronger than you think.", "es": "Eres más fuerte de lo que crees.", "fr": "Tu es plus fort que tu ne le penses.", "it": "Sei più forte di quanto pensi.", "pt": "És mais forte do que pensas."],
